/**
 * T164 F1 (2026-09-26): in the static demo, parameterized answers replay
 * ONE frozen example no matter what the visitor asked (the City Centre
 * 10→2 answer to a Meadowvale 38→42 query). A replayed result card must
 * say so — an unnamed canonical answer reads as broken to a stranger.
 *
 * Rendered only when static-patch actually replayed that endpoint this
 * page-load (see pathWasReplayed). `whatYouAsked` re-states the visitor's
 * input; `replayIs` names the frozen example so the mismatch is
 * self-explaining instead of looking like a bug.
 */
export default function ReplayNotice({
  whatYouAsked,
  replayIs,
}: {
  whatYouAsked: string;
  replayIs: string;
}) {
  return (
    <div
      role="note"
      data-testid="replay-notice"
      className="rounded border border-[color:var(--color-bottleneck)]/40 bg-[color:var(--color-bottleneck)]/10 px-2.5 py-1.5 text-xs text-text-secondary"
    >
      <strong className="text-text-primary">Demo replay:</strong> you asked about{' '}
      {whatYouAsked} — this answer is the frozen example ({replayIs}). Live
      answers for any query appear when the live API is up (daily 3–10pm ET).
    </div>
  );
}
